// defaultEmbedder lazily loads the bundled static model once. A load failure
// (corrupt/absent asset) yields nil so semantic recall degrades to the lexical
// path rather than failing — embeddings are optional by design.
var (
	defaultEmbedderOnce sync.Once
	defaultEmbedderInst Embedder
)

// configuredEmbedder resolves the process embedder from ENTIRE_BRAIN_EMBEDDER,
// returning the embedder plus an optional human warning when an opt-in could not
// be honored. ENTIRE_BRAIN_EMBEDDER=ollama swaps the bundled Model2Vec static
// model for EmbeddingGemma served over a local Ollama (or node-llama-cpp) HTTP
// endpoint. When that opt-in is selected but the server does not return an
// embedding (unreachable, wrong model, or an error response), it falls
// back to the bundled Model2Vec model — keeping a single consistent vector space
// (and cache namespace) — rather than silently degrading the semantic arm to
// lexical-only, and reports the fallback so the user knows their opt-in did not
// take effect.
func configuredEmbedder() (Embedder, string) {
	if strings.EqualFold(strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_EMBEDDER")), "ollama") {
		o := newOllamaEmbedder()
		if o == nil {
			// The loopback guard rejected ENTIRE_BRAIN_EMBED_URL (non-loopback
			// or unparseable). The exact scenario the guard hardens must
			// degrade to the bundled model, not panic.
			base := "ENTIRE_BRAIN_EMBEDDER=ollama set but ENTIRE_BRAIN_EMBED_URL is not a loopback URL (rejected to keep embeddings on-box)"
			if e, err := loadStaticEmbedder(entirebrain.EmbedModel); err == nil {
				return e, base + "; falling back to the bundled Model2Vec embedder"
			}
			return nil, base + " and the bundled Model2Vec fallback could not be loaded; semantic retrieval is unavailable (lexical only)"
		}
		if o.reachable() {
			return o, ""
		}
		base := fmt.Sprintf("ENTIRE_BRAIN_EMBEDDER=ollama set but the embed server at %s did not return an embedding (unreachable, wrong model, or an error response)", o.url)
		if e, err := loadStaticEmbedder(entirebrain.EmbedModel); err == nil {
			return e, base + "; falling back to the bundled Model2Vec embedder"
		}
		// The bundled fallback also failed to load — there is no semantic arm.
		return nil, base + " and the bundled Model2Vec fallback could not be loaded; semantic retrieval is unavailable (lexical only)"
	}
	if e, err := loadStaticEmbedder(entirebrain.EmbedModel); err == nil {
		return e, ""
	}
	// The bundled asset is the default embedder; if it cannot be loaded (e.g. a
	// corrupt build) surface it rather than silently degrading to lexical-only.
	return nil, "the bundled Model2Vec embedder could not be loaded; semantic retrieval is unavailable (lexical only)"
}

func defaultEmbedder() Embedder {
	defaultEmbedderOnce.Do(func() {
		e, warn := configuredEmbedder()
		if warn != "" {
			fmt.Fprintln(os.Stderr, "entire-brain: "+warn)
		}
		defaultEmbedderInst = e
# Embedder benchmark (Model2Vec vs EmbeddingGemma)

Measures fact-retrieval quality of the bundled pure-Go Model2Vec embedder against
the Stage 1b transformer (EmbeddingGemma-300M), across one or more repos. Same
lexical arm and same provenance-labeled task set per repo, so the delta isolates
the embedder. This is the gate for the Stage 1b cgo bet (see `../../` and the
alignment plan's "Embedder gate").

## Historical Local Result (2026-06-08)

An operator-run sweep observed EmbeddingGemma beating Model2Vec by **+14%
useful/1k pooled** over 60 tasks on two repos (`entire-brain` +15%, `podcasts`
+13%). The raw artifacts are not committed here, so treat this as a historical
local note, not release evidence. Re-run the current harness and commit
sanitized summaries before using the number in public claims.

## Run it

```sh
# 1. build the brain binary
(cd ../.. && go build -o entire-brain ./cmd/entire-brain)

# 2. optionally start the EmbeddingGemma embed server (qmd's runner, no cgo).
#    This setup downloads a model; skip it for offline/no-egress release checks.
#    Run npm from THIS directory — package.json here anchors the install so npm
#    can't resolve a parent directory (e.g. $HOME) as the package root.
npm install
curl -L -o /tmp/eg.gguf \
  https://huggingface.co/ggml-org/embeddinggemma-300M-GGUF/resolve/main/embeddinggemma-300M-Q8_0.gguf
GGUF=/tmp/eg.gguf PORT=11500 node embed-server.mjs &

# 3. benchmark a list of repos (each needs exported Entire session history)
./run.sh ~/Projects/entire-brain ~/Projects/podcasts

# 4. print the per-repo + pooled table
./agg.py
```

## Notes

- `run.sh` distills facts with a cheap model (`MODEL=gpt-5.4-mini`, override via
  env). Distilling is the slow step (one agent run per repo).
- The GGUF is the **canonical** ggml-org build (open, not Gemma-gated). The
  Ollama-pulled blob is *not* portable to plain llama.cpp (314 vs 316 tensors).
- The brain's opt-in EmbeddingGemma backend is selected with
  `ENTIRE_BRAIN_EMBEDDER=ollama` + `ENTIRE_BRAIN_EMBED_URL` (any endpoint with
  Ollama's `/api/embed` shape — this server, or a real Ollama).
- Caveat: tasks are self-labeled from each repo's session provenance; `eval-gen
  --refine` (agent-judged) tightens labels but costs agent calls.
// EmbeddingGemma embed server for the Stage 1b benchmark (qmd's runner: the GGUF
// runs in-process via node-llama-cpp's prebuilt llama.cpp — no Ollama, no build).
// Exposes Ollama's /api/embed shape so the brain's opt-in embedder can reach it.
// The brain's ollamaEmbedder POSTs {"model": "…", "input": "…"}; only "input" is
// used here (extra fields like "model" are ignored):
//   POST {"model": "…", "input": "…"} -> {"embeddings": [[...768 floats...]]}
//
// Setup (see README.md):
//   npm install   # from scripts/bench — package.json there anchors the install
//   # canonical GGUF (open, not Gemma-gated):
//   #   ggml-org/embeddinggemma-300M-GGUF / embeddinggemma-300M-Q8_0.gguf
//   GGUF=/path/to/embeddinggemma-300M-Q8_0.gguf PORT=11500 node embed-server.mjs
//
// Then point the brain at it:
//   ENTIRE_BRAIN_EMBEDDER=ollama ENTIRE_BRAIN_EMBED_URL=http://localhost:11500 \
//     entire-brain facts eval --tasks tasks.json --branch main --semantic --json
import http from "node:http";
import { getLlama } from "node-llama-cpp";

const modelPath = process.env.GGUF;
const port = Number(process.env.PORT || 11500);
// Bind loopback by default so this compute-heavy endpoint isn't exposed on a
// shared machine; set HOST=0.0.0.0 to opt into all interfaces.
const host = process.env.HOST || "127.0.0.1";
if (!modelPath) {
  console.error("set GGUF=/path/to/embeddinggemma-300M-Q8_0.gguf");
  process.exit(1);
}

console.log("loading", modelPath);
const llama = await getLlama();
const model = await llama.loadModel({ modelPath });
const ctx = await model.createEmbeddingContext();
const probe = await ctx.getEmbeddingFor("title: none | text: probe");
console.log("ready: dim =", probe.vector.length, "on :" + port);

http.createServer((req, res) => {
  if (req.method !== "POST") { res.writeHead(405); res.end(); return; }
  // Accept the embed endpoint only (the brain points ENTIRE_BRAIN_EMBED_URL at the
  // root; "/api/embed" matches Ollama's shape). 404 anything else so the server
  // isn't an accidental catch-all if more endpoints are added later.
  const path = (req.url || "/").split("?")[0];
  if (path !== "/" && path !== "/api/embed") { res.writeHead(404); res.end(); return; }
  const chunks = [];
  let size = 0;
  let aborted = false;
  const MAX_BODY = 1 << 20; // 1 MiB — embed inputs are short; cap accidental/huge requests
  req.on("data", (c) => {
    if (aborted) return;
    size += c.length; // c is a Buffer; .length is bytes, not UTF-16 code units
    if (size > MAX_BODY) {
      aborted = true;
      res.writeHead(413, { "content-type": "application/json" });
      res.end(JSON.stringify({ error: "request body too large" }));
      req.destroy();
      return;
    }
    chunks.push(c);
  });
  req.on("end", async () => {
    if (aborted) return;
    // 400 for a malformed/incomplete request; 500 only for embedder/runtime faults.
    let input;
    try {
      ({ input } = JSON.parse(Buffer.concat(chunks).toString("utf8")));
    } catch {
      res.writeHead(400, { "content-type": "application/json" });
      res.end(JSON.stringify({ error: "invalid JSON body" }));
      return;
    }
    if (typeof input !== "string" || input.length === 0) {
      res.writeHead(400, { "content-type": "application/json" });
      res.end(JSON.stringify({ error: "missing or empty 'input' string" }));
      return;
    }
    try {
      const emb = await ctx.getEmbeddingFor(input);
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ embeddings: [Array.from(emb.vector)] }));
    } catch (e) {
      res.writeHead(500, { "content-type": "application/json" });
      res.end(JSON.stringify({ error: String(e) }));
    }
  });
}).listen(port, host, () => console.log(`embed server listening on ${host}:${port}`));

